-- post: laptop-thermals-what-reviews-miss (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30026, now(), now(), 'seed', 'laptop-thermals-what-reviews-miss', 'POST', 0, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '2 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390003, "categoryIds": [-353, -351], "tags": ["laptops", "thermals", "benchmarks"], "authorName": "Priya Raman", "featured": true}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300051, now(), now(), 'seed', '<p>Every thin laptop is fast for thirty seconds. The interesting question is what it does in minute twelve.</p><h2>Why peak scores mislead</h2><p>Manufacturers size the cooling for a short burst, because that is what a benchmark measures. Under a thirty-minute sustained load, the same machine can settle 40% below its headline number — and that is the number you get while rendering, compiling or exporting.</p><h2>How we test</h2><ul><li>Thirty minutes of combined CPU and GPU load in a 22°C room</li><li>Fan noise recorded at 50 cm, A-weighted</li><li>Keyboard-deck surface temperature at three points</li></ul><h2>What we look for</h2><p>A machine that settles honestly at 70% of peak and stays quiet beats one that spikes to 100% and then collapses to 45% with the fans at 48 dB. The second looks better in a chart and is worse to own.</p><h2>The chassis that surprised us</h2><p>Two of the three quietest machines this year are the heaviest in their class. Cooling takes volume; there is no way around the physics.</p>', 'Laptop thermals: what most reviews miss', 'Laptop thermals: what most reviews miss', 'Why sustained load matters more than peak scores, and how we measure it before a laptop reaches the catalogue.', 'laptops, thermals, benchmarks', 'Laptop thermals: what most reviews miss | The Bench', 'laptop-thermals-what-reviews-miss', 'en', -30026, 'TRANSLATED', 'A thirty-second benchmark flatters every laptop. Thirty minutes separates them.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300052, now(), now(), 'seed', '<p>Tout portable fin est rapide pendant trente secondes. La question intéressante, c''est la douzième minute.</p><h2>Pourquoi les scores de crête trompent</h2><p>Les constructeurs dimensionnent le refroidissement pour une salve courte, puisque c''est ce que mesure un benchmark. Sur trente minutes de charge continue, la même machine peut se stabiliser 40 % sous son chiffre d''annonce — et c''est ce chiffre-là que vous obtenez en rendu, en compilation ou à l''export.</p><h2>Notre protocole</h2><ul><li>Trente minutes de charge combinée CPU et GPU dans une pièce à 22 °C</li><li>Bruit de ventilation relevé à 50 cm, pondéré A</li><li>Température de surface du clavier en trois points</li></ul><h2>Ce que nous cherchons</h2><p>Une machine qui se stabilise honnêtement à 70 % de sa crête en restant silencieuse vaut mieux qu''une autre qui monte à 100 % puis s''effondre à 45 % avec les ventilateurs à 48 dB. La seconde paraît meilleure sur un graphique et se vit moins bien.</p><h2>Le châssis qui nous a surpris</h2><p>Deux des trois machines les plus silencieuses de l''année sont les plus lourdes de leur catégorie. Refroidir demande du volume ; la physique ne se contourne pas.</p>', 'Thermique des portables : ce que les tests oublient', 'Thermique des portables : ce que les tests oublient', 'Pourquoi la charge soutenue compte plus que le score de crête, et comment nous la mesurons.', 'laptops, thermals, benchmarks', 'Thermique des portables | Au banc d''essai', 'thermique-des-portables', 'fr', -30026, 'TRANSLATED', 'Trente secondes de benchmark flattent n''importe quel portable. Trente minutes les départagent.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-3001, -390003, 'CONTENT', '-30026', 'Laptop thermals: what most reviews miss', -30026, 'POST', 'hero')
on conflict (id) do nothing;

-- post: anc-headphones-measured (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30027, now(), now(), 'seed', 'anc-headphones-measured', 'POST', 1, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '8 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390004, "categoryIds": [-351], "tags": ["headphones", "anc", "audio"], "authorName": "Daniel Okafor", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300053, now(), now(), 'seed', '<h2>Cancellation is a low-frequency trick</h2><p>Active cancellation works well below about 1 kHz and poorly above it. That is why a plane cabin goes quiet and a nearby conversation does not.</p><h2>The number that matters</h2><p>Attenuation at 100 Hz, in decibels, on a measurement head. The best sets on our bench reach 28–32 dB there; a mid-range set manages 18–20; the difference is the entire experience on a long flight.</p><h2>What the box does not say</h2><ul><li>Cancellation depth usually costs battery, sometimes 30% of it</li><li>Strong cancellation can produce a pressure sensation some people cannot tolerate</li><li>Wind noise handling varies far more between models than cancellation depth does</li></ul><h2>Try before you commit</h2><p>Pressure sensitivity is individual and no measurement predicts it. Our thirty-day window on opened headphones exists precisely for this.</p>', 'Noise cancelling, measured rather than described', 'Noise cancelling, measured rather than described', 'How active cancellation is measured, why low frequencies matter most, and what marketing figures leave out.', 'headphones, anc, audio', 'Noise cancelling, measured | The Bench', 'anc-headphones-measured', 'en', -30027, 'TRANSLATED', 'Every set claims to cancel noise. Only the 100 Hz figure tells you whether it cancels the noise you have.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300054, now(), now(), 'seed', '<h2>La réduction est une affaire de graves</h2><p>La réduction active fonctionne bien en dessous de 1 kHz et mal au-dessus. D''où une cabine d''avion qui se tait et une conversation voisine qui persiste.</p><h2>Le chiffre qui compte</h2><p>L''atténuation à 100 Hz, en décibels, sur tête de mesure. Les meilleurs casques de notre banc atteignent 28 à 32 dB ; un modèle milieu de gamme plafonne à 18–20 ; l''écart, c''est toute l''expérience d''un vol long-courrier.</p><h2>Ce que la boîte ne dit pas</h2><ul><li>La profondeur de réduction coûte de l''autonomie, parfois 30 %</li><li>Une réduction forte crée une sensation de pression que certains ne supportent pas</li><li>La tenue au vent varie bien plus entre modèles que la profondeur de réduction</li></ul><h2>Essayez avant de vous engager</h2><p>La sensibilité à la pression est individuelle et aucune mesure ne la prédit. Nos trente jours sur casque ouvert existent exactement pour cela.</p>', 'La réduction de bruit, mesurée plutôt que décrite', 'La réduction de bruit, mesurée plutôt que décrite', 'Comment se mesure la réduction active, pourquoi les basses fréquences priment, et ce que les fiches omettent.', 'headphones, anc, audio', 'La réduction de bruit, mesurée | Au banc d''essai', 'reduction-de-bruit-mesuree', 'fr', -30027, 'TRANSLATED', 'Tous les casques prétendent réduire le bruit. Seul le chiffre à 100 Hz dit s''ils réduisent le vôtre.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
VALUES (-3002, -390004, 'CONTENT', '-30027', 'Noise cancelling, measured rather than described', -30027, 'POST', 'hero')
