-- post: make-your-battery-last (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30028, now(), now(), 'seed', 'make-your-battery-last', 'POST', 2, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '16 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390005, "categoryIds": [-352], "tags": ["battery", "maintenance", "phones"], "authorName": "Priya Raman", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300055, now(), now(), 'seed', '<h2>Three things matter</h2><ol><li><strong>Heat.</strong> A cell held at 35°C degrades roughly twice as fast as one at 25°C. Charging in a hot car is the single worst habit.</li><li><strong>Time at 100%.</strong> Sitting fully charged for hours stresses the cell. Overnight charging is fine if the device caps at 80% until morning — most now do.</li><li><strong>Deep discharge.</strong> Regularly running to 0% costs more cycles than any charging speed does.</li></ol><h2>Things that do not matter</h2><ul><li>Using a fast charger — the device controls the rate, not the brick</li><li>Charging to 100% occasionally, when you need the range</li><li>Third-party cables, provided they are certified</li></ul><h2>The honest expectation</h2><p>A phone battery loses about 20% of its capacity in two years of normal use. That is chemistry, not a defect, and no habit prevents it entirely.</p>', 'Make a lithium battery last', 'Make a lithium battery last', 'What actually degrades lithium cells, what does not, and the three habits that make a measurable difference.', 'battery, maintenance, phones', 'Make a lithium battery last | How-to', 'make-your-battery-last', 'en', -30028, 'TRANSLATED', 'Heat kills batteries faster than charging does. Almost everything else you have read is noise.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300056, now(), now(), 'seed', '<h2>Trois facteurs comptent</h2><ol><li><strong>La chaleur.</strong> Une cellule maintenue à 35 °C vieillit environ deux fois plus vite qu''à 25 °C. Charger dans une voiture au soleil est la pire habitude.</li><li><strong>Le temps passé à 100 %.</strong> Rester chargé à bloc pendant des heures fatigue la cellule. Charger la nuit ne pose pas de problème si l''appareil plafonne à 80 % jusqu''au matin, ce que la plupart font désormais.</li><li><strong>La décharge profonde.</strong> Descendre régulièrement à 0 % coûte plus de cycles que n''importe quelle vitesse de charge.</li></ol><h2>Ce qui ne compte pas</h2><ul><li>Utiliser un chargeur rapide — c''est l''appareil qui pilote le débit, pas le bloc</li><li>Charger à 100 % occasionnellement, quand vous avez besoin d''autonomie</li><li>Les câbles tiers, s''ils sont certifiés</li></ul><h2>L''attente honnête</h2><p>Une batterie de téléphone perd environ 20 % de sa capacité en deux ans d''usage normal. C''est de la chimie, pas un défaut, et aucune habitude ne l''empêche totalement.</p>', 'Faire durer une batterie lithium', 'Faire durer une batterie lithium', 'Ce qui dégrade réellement les cellules lithium, ce qui ne les dégrade pas, et les trois habitudes utiles.', 'battery, maintenance, phones', 'Faire durer une batterie lithium | Tutoriels', 'faire-durer-une-batterie', 'fr', -30028, 'TRANSLATED', 'La chaleur tue les batteries plus vite que la charge. Presque tout le reste est du bruit.', null, null, null)
on conflict (description_id) do nothing;
