-- post: tv-settings-out-of-the-box (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30029, now(), now(), 'seed', 'tv-settings-out-of-the-box', 'POST', 3, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '25 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390006, "categoryIds": [-352, -351], "tags": ["tv", "calibration", "picture"], "authorName": "Daniel Okafor", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300057, now(), now(), 'seed', '<h2>1. Turn off motion smoothing</h2><p>It interpolates frames the director never shot. Film looks like video, and the effect has a name for a reason.</p><h2>2. Switch out of Vivid</h2><p>Vivid — or Dynamic — is calibrated to survive fluorescent store lighting. Filmmaker, Cinema or Movie mode is far closer to the reference the content was graded against.</p><h2>3. Take sharpness to zero</h2><p>The sharpness control does not add detail; it adds a white halo around edges. Zero is neutral.</p><h2>4. Leave local dimming on high</h2><p>Contrary to forum advice, on modern panels high local dimming improves black level far more than it introduces blooming.</p><h2>5. Enable game mode for consoles</h2><p>It bypasses the processing that costs 60–100 ms of input lag. Nothing else on this list is as noticeable.</p>', 'The five TV settings to change on day one', 'The five TV settings to change on day one', 'Motion smoothing, picture mode, sharpness, local dimming and game mode — what to change and why.', 'tv, calibration, picture', 'Five TV settings to change on day one | How-to', 'tv-settings-out-of-the-box', 'en', -30029, 'TRANSLATED', 'Showroom mode exists to win a lit store. In a living room it is simply wrong.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300058, now(), now(), 'seed', '<h2>1. Désactiver la fluidification</h2><p>Elle interpole des images que le réalisateur n''a jamais tournées. Le film prend une allure de vidéo, et l''effet porte un nom pour de bonnes raisons.</p><h2>2. Quitter le mode Vif</h2><p>Vif — ou Dynamique — est calibré pour survivre aux néons d''un magasin. Les modes Filmmaker, Cinéma ou Film sont bien plus proches de la référence d''étalonnage.</p><h2>3. Mettre la netteté à zéro</h2><p>Le réglage de netteté n''ajoute pas de détail : il ajoute un halo blanc autour des contours. Zéro est neutre.</p><h2>4. Laisser la gradation locale au maximum</h2><p>Contrairement aux conseils de forum, sur les dalles récentes une gradation locale élevée améliore bien plus le niveau de noir qu''elle n''introduit de halo.</p><h2>5. Activer le mode jeu pour les consoles</h2><p>Il contourne les traitements qui coûtent 60 à 100 ms de latence. Rien d''autre dans cette liste ne se remarque autant.</p>', 'Les cinq réglages TV à changer le premier jour', 'Les cinq réglages TV à changer le premier jour', 'Fluidification, mode image, netteté, gradation locale et mode jeu : quoi changer et pourquoi.', 'tv, calibration, picture', 'Cinq réglages TV à changer | Tutoriels', 'cinq-reglages-tv', 'fr', -30029, 'TRANSLATED', 'Le mode magasin existe pour gagner un rayon éclairé. Dans un salon, il est simplement faux.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.media_usage (id, asset_id, owner_kind, owner_ref, owner_title, content_id, content_type, field)
