-- post: refurbished-what-we-replace (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30030, now(), now(), 'seed', 'refurbished-what-we-replace', 'POST', 4, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '38 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390007, "categoryIds": [-353], "tags": ["refurbished", "repair", "trade-in"], "authorName": "Marcus Hale", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300059, now(), now(), 'seed', '<h2>Always replaced</h2><ul><li>The battery, if capacity is under 90% — not 80%, which is the industry line</li><li>Ear tips, thermal paste, and any adhesive seal opened during service</li><li>Cracked glass, even cosmetic hairlines on a screen</li></ul><h2>Tested and kept</h2><p>Panels, keyboards, ports and speakers are measured against the same bench spec as new stock. A port that passes ten thousand insertion cycles is a port that stays.</p><h2>When we scrap</h2><p>Any board with liquid-damage indicators triggered, any chassis with structural deformation, and any device whose manufacturer has stopped issuing security updates. The first two are safety; the third is honesty.</p><h2>What you get</h2><p>Our own one-year warranty, the full bench report, and a device that failed nothing rather than one that failed nothing visible.</p>', 'Refurbished: what we replace before reselling', 'Refurbished: what we replace before reselling', 'The parts we always change on a trade-in, the ones we test and keep, and when a device is scrapped.', 'refurbished, repair, trade-in', 'Refurbished: what we replace | The Bench', 'refurbished-what-we-replace', 'en', -30030, 'TRANSLATED', 'Six devices in ten come back to life. The other four never leave the bench.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300060, now(), now(), 'seed', '<h2>Systématiquement remplacé</h2><ul><li>La batterie si la capacité est sous 90 % — pas 80 %, la norme du secteur</li><li>Embouts, pâte thermique et tout joint adhésif ouvert pendant l''intervention</li><li>Verre fêlé, même une micro-fissure cosmétique sur un écran</li></ul><h2>Testé et conservé</h2><p>Dalles, claviers, connecteurs et haut-parleurs sont mesurés selon le même protocole que le neuf. Un connecteur qui tient dix mille cycles d''insertion reste en place.</p><h2>Quand nous mettons au rebut</h2><p>Toute carte dont les témoins de liquide sont déclenchés, tout châssis déformé structurellement, et tout appareil dont le constructeur a cessé les mises à jour de sécurité. Les deux premiers relèvent de la sécurité ; le troisième, de l''honnêteté.</p><h2>Ce que vous recevez</h2><p>Notre garantie d''un an, le rapport de banc complet, et un appareil qui n''a rien raté — pas un appareil qui n''a rien raté de visible.</p>', 'Reconditionné : ce que nous remplaçons avant de revendre', 'Reconditionné : ce que nous remplaçons avant de revendre', 'Les pièces systématiquement changées sur une reprise, celles que nous testons et gardons, et les cas de mise au rebut.', 'refurbished, repair, trade-in', 'Reconditionné : ce que nous remplaçons | Au banc d''essai', 'reconditionne-ce-que-nous-remplacons', 'fr', -30030, 'TRANSLATED', 'Six appareils sur dix repartent. Les quatre autres ne quittent jamais le banc.', null, null, null)
on conflict (description_id) do nothing;
