-- post: usb-c-cables-are-not-equal (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30031, now(), now(), 'seed', 'usb-c-cables-are-not-equal', 'POST', 5, true, '65f023632bc46470c104b75f', 'PUBLISHED', now() - interval '55 days', null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, '{"heroMediaId": -390003, "categoryIds": [-352], "tags": ["usb-c", "cables", "charging"], "authorName": "Marcus Hale", "featured": false}')
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300061, now(), now(), 'seed', '<h2>One shape, four capabilities</h2><p>A USB-C cable can carry 60 W or 240 W, and 480 Mbps or 40 Gbps, in any combination. The connector tells you nothing.</p><h2>The e-marker</h2><p>Anything above 60 W needs a chip inside the cable declaring its rating. Without it the charger falls back to 60 W, which is why a 140 W laptop charges slowly on the wrong cable and nothing warns you.</p><h2>How to tell them apart</h2><ul><li>Look for the printed wattage or the certification logo on the connector shell</li><li>Charge-only cables are usually thinner and lighter; a 40 Gbps cable is noticeably stiff</li><li>Length matters: passive 40 Gbps cables stop working reliably past about 80 cm</li></ul><h2>What we stock</h2><p>Only certified cables, with the rating printed on the connector. It costs a little more and removes an entire category of support ticket.</p>', 'USB-C cables are not interchangeable', 'USB-C cables are not interchangeable', 'Power delivery, data rates, e-marker chips and how to tell a 240 W cable from a 60 W one.', 'usb-c, cables, charging', 'USB-C cables are not interchangeable | How-to', 'usb-c-cables-are-not-equal', 'en', -30031, 'TRANSLATED', 'Same connector, wildly different cables. The one in the drawer may be why your laptop charges slowly.', null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300062, now(), now(), 'seed', '<h2>Une forme, quatre capacités</h2><p>Un câble USB-C peut transporter 60 W ou 240 W, et 480 Mbit/s ou 40 Gbit/s, dans n''importe quelle combinaison. Le connecteur ne dit rien.</p><h2>La puce e-marker</h2><p>Au-delà de 60 W, une puce intégrée doit déclarer la capacité du câble. Sans elle, le chargeur retombe à 60 W : c''est pourquoi un portable de 140 W charge lentement sur le mauvais câble, sans le moindre avertissement.</p><h2>Comment les distinguer</h2><ul><li>Cherchez la puissance imprimée ou le logo de certification sur la coque du connecteur</li><li>Les câbles de charge seule sont plus fins et plus souples ; un câble 40 Gbit/s est nettement rigide</li><li>La longueur compte : un câble passif 40 Gbit/s décroche au-delà de 80 cm environ</li></ul><h2>Ce que nous référençons</h2><p>Uniquement des câbles certifiés, puissance imprimée sur le connecteur. Cela coûte un peu plus cher et supprime toute une catégorie de tickets de support.</p>', 'Les câbles USB-C ne se valent pas', 'Les câbles USB-C ne se valent pas', 'Puissance, débit de données, puce e-marker, et comment distinguer un câble 240 W d''un câble 60 W.', 'usb-c, cables, charging', 'Les câbles USB-C ne se valent pas | Tutoriels', 'les-cables-usb-c-ne-se-valent-pas', 'fr', -30031, 'TRANSLATED', 'Même connecteur, câbles radicalement différents. Celui du tiroir explique peut-être votre charge lente.', null, null, null)
on conflict (description_id) do nothing;
